34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.rest.validation.DuplicateHouseholdException;
41	import org.springframework.samples.petclinic.rest.validation.DuplicateTelephoneException;
42	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
43	import org.springframework.samples.petclinic.rest.validation.HouseholdDuplicateValidator;
44	import org.springframework.samples.petclinic.rest.validation.MissingOwnerFieldsException;
45	import org.springframework.samples.petclinic.rest.validation.OwnerFieldsValidator;
46	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    private final ClinicService clinicService;
66	
67	    private final OwnerMapper ownerMapper;
68	
69	    private final PetMapper petMapper;
70	
71	    private final VisitMapper visitMapper;
72	
73	    private final OwnerFieldsValidator ownerFieldsValidator;
74	
75	    private final HouseholdDuplicateValidator householdDuplicateValidator;
76	
77	    private final TelephoneNormalizer telephoneNormalizer;
78	
79	    private final EmailNormalizer emailNormalizer;
80	
81	    private final CustomerCodeGenerator customerCodeGenerator;
82	
83	    public OwnerRestControllerV1(ClinicService clinicService,
84	                                 OwnerMapper ownerMapper,
85	                                 PetMapper petMapper,
86	                                 VisitMapper visitMapper,
87	                                 OwnerFieldsValidator ownerFieldsValidator,
88	                                 HouseholdDuplicateValidator householdDuplicateValidator,
89	                                 TelephoneNormalizer telephoneNormalizer,
90	                                 EmailNormalizer emailNormalizer,
91	                                 CustomerCodeGenerator customerCodeGenerator) {
92	        this.clinicService = clinicService;
93	        this.ownerMapper = ownerMapper;
94	        this.petMapper = petMapper;
95	        this.visitMapper = visitMapper;
96	        this.ownerFieldsValidator = ownerFieldsValidator;
97	        this.householdDuplicateValidator = householdDuplicateValidator;
98	        this.telephoneNormalizer = telephoneNormalizer;
99	        this.emailNormalizer = emailNormalizer;
100	        this.customerCodeGenerator = customerCodeGenerator;
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
106	        Collection<Owner> owners;
107	        if (lastName != null) {
108	            owners = this.clinicService.findOwnerByLastName(lastName);
109	        } else {
110	            owners = this.clinicService.findAllOwners();
111	        }
112	        if (owners.isEmpty()) {
113	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
114	        }
115	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
121	        Owner owner = this.clinicService.findOwnerById(ownerId);
122	        if (owner == null) {
123	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
124	        }
125	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
126	    }
127	
128	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
129	    @Override
130	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
131	        List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFieldsDto);
132	        if (!missingFields.isEmpty()) {
133	            throw new MissingOwnerFieldsException(missingFields);
134	        }
135	        HttpHeaders headers = new HttpHeaders();
136	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
137	        rejectDuplicateHousehold(owner, ownerFieldsDto);
138	        String normalizedTelephone = telephoneNormalizer.normalize(owner.getTelephone());
139	        if (!this.clinicService.findOwnersByTelephone(normalizedTelephone).isEmpty()) {
140	            throw new DuplicateTelephoneException(normalizedTelephone);
141	        }
142	        owner.setTelephone(normalizedTelephone);
143	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
144	        if (owner.getRegistrationDate() == null) {
145	            owner.setRegistrationDate(LocalDate.now());
146	        }
147	        owner.setCustomerCode(
148	            customerCodeGenerator.generate(owner.getLastName(), clinicService.countOwners()));
149	        this.clinicService.saveOwner(owner);
150	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
151	        headers.setLocation(UriComponentsBuilder.newInstance()
152	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
153	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
154	    }
155	
156	    /**
157	     * Rejects creating an owner that shares a household (same last name and address, compared
158	     * case-insensitively with collapsed whitespace) with an existing owner, unless the request
159	     * opted in via {@code sharesHousehold}.
160	     *
161	     * @throws DuplicateHouseholdException if a conflicting owner exists and the caller did not opt in
162	     */
163	    private void rejectDuplicateHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
164	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
165	            return;
166	        }
167	        Collection<Owner> sameLastName = this.clinicService.findOwnersByLastNameIgnoreCase(owner.getLastName());
168	        if (householdDuplicateValidator.sharesHouseholdWithExisting(owner, sameLastName)) {
169	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
170	        }
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Override
175	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
176	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
177	        if (currentOwner == null) {
178	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	        }
180	        currentOwner.setAddress(ownerFieldsDto.getAddress());
181	        currentOwner.setCity(ownerFieldsDto.getCity());
182	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
183	        currentOwner.setLastName(ownerFieldsDto.getLastName());
184	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
185	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
186	        this.clinicService.saveOwner(currentOwner);
187	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
188	    }
189	
190	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
191	    @Transactional
192	    @Override
193	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
194	        Owner owner = this.clinicService.findOwnerById(ownerId);
195	        if (owner == null) {
196	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
197	        }
198	        this.clinicService.deleteOwner(owner);
199	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
200	    }
201	
202	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
203	    @Override
204	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
205	        Owner owner = this.clinicService.findOwnerById(ownerId);
206	        if (owner == null) {
207	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
208	        }
209	        HttpHeaders headers = new HttpHeaders();
210	        Pet pet = petMapper.toPet(petFieldsDto);
211	        owner.setId(ownerId);
212	        pet.setOwner(owner);
213	        pet.getType().setName(null);
214	        this.clinicService.savePet(pet);
215	        PetDto petDto = petMapper.toPetDto(pet);
216	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
217	            .buildAndExpand(pet.getId()).toUri());
218	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
219	    }
220	
221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Override
223	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
224	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
225	        if (currentOwner != null) {
226	            Pet currentPet = this.clinicService.findPetById(petId);
227	            if (currentPet != null) {
228	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
229	                currentPet.setName(petFieldsDto.getName());
230	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
231	                this.clinicService.savePet(currentPet);
232	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
233	            }
234	        }
235	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
236	    }
237	
238	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
239	    @Override
240	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
241	        HttpHeaders headers = new HttpHeaders();
242	        Visit visit = visitMapper.toVisit(visitFieldsDto);
243	        Pet pet = new Pet();
244	        pet.setId(petId);
245	        visit.setPet(pet);
246	        this.clinicService.saveVisit(visit);
247	        VisitDto visitDto = visitMapper.toVisitDto(visit);
248	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
249	            .buildAndExpand(visit.getId()).toUri());
250	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
251	    }
252	
253	
254	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
255	    @Override
256	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
257	        Owner owner = this.clinicService.findOwnerById(ownerId);
258	        if (owner != null) {
259	            Pet pet = owner.getPet(petId);
260	            if (pet != null) {
261	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
262	            }
263	        }
264	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
265	    }
266	}
