26	/**
27	 * Jackson customization for owner payloads.
28	 * <p>
29	 * {@code sharesHousehold} is a write-only hint accepted only when creating an owner (see the
30	 * {@code OwnerFields} schema); it is never stored, so it has nothing to return. The generated
31	 * {@link OwnerDto} nevertheless inherits the property from the shared schema, so a mix-in marks
32	 * it {@link JsonProperty.Access#WRITE_ONLY} to keep it out of owner responses.
33	 */
34	@Configuration
35	public class OwnerJacksonConfig {
36	
37	    @Bean
38	    JsonMapperBuilderCustomizer ownerSharesHouseholdWriteOnlyCustomizer() {
39	        return builder -> builder.addMixIn(OwnerDto.class, OwnerDtoMixin.class);
40	    }
41	
42	    /** Hides the write-only {@code sharesHousehold} hint from serialized {@link OwnerDto} responses. */
43	    abstract static class OwnerDtoMixin {
44	
45	        @JsonProperty(access = JsonProperty.Access.WRITE_ONLY)
46	        abstract Boolean getSharesHousehold();
47	    }
48	}
