24	
25	/**
26	 * Decides whether a would-be owner shares a household with an existing one, i.e. has the
27	 * same last name and address. Both fields are compared case-insensitively and with runs of
28	 * whitespace collapsed to a single space, so cosmetic differences do not defeat the check.
29	 */
30	@Component
31	public class HouseholdDuplicateValidator {
32	
33	    /**
34	     * @param candidate the owner about to be created
35	     * @param existingOwners owners already stored (typically pre-filtered by last name)
36	     * @return {@code true} when any existing owner has the same normalized last name and
37	     *         address as the candidate
38	     */
39	    public boolean sharesHouseholdWithExisting(Owner candidate, Collection<Owner> existingOwners) {
40	        String lastName = normalize(candidate.getLastName());
41	        String address = normalize(candidate.getAddress());
42	        return existingOwners.stream().anyMatch(existing ->
43	            normalize(existing.getLastName()).equals(lastName)
44	                && normalize(existing.getAddress()).equals(address));
45	    }
46	
47	    /** Trim, collapse internal whitespace and lower-case, so equality ignores case and spacing. */
48	    private String normalize(String value) {
49	        if (value == null) {
50	            return "";
51	        }
52	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
53	    }
54	}
