48	/**
49	 * Global Exception handler for REST controllers.
50	 * <p>
51	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
52	 *
53	 * @author Vitaliy Fedoriv
54	 * @author Alexander Dudkin
55	 */
56	@ControllerAdvice
57	public class ExceptionControllerAdvice {
58	
59	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
60	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
61	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
62	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
63	
64	    private final OwnerFieldsValidator ownerFieldsValidator;
65	
66	    public ExceptionControllerAdvice(OwnerFieldsValidator ownerFieldsValidator) {
67	        this.ownerFieldsValidator = ownerFieldsValidator;
68	    }
69	
70	    /**
71	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
72	     * class.
73	     *
74	     * @param e     Object referring to the thrown exception.
75	     * @param status HTTP response status.
76	     * @param url URL request.
77	     */
78	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
79	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
80	        problemDetail.setType(URI.create(url.toString()));
81	        problemDetail.setTitle(e.getClass().getSimpleName());
82	        problemDetail.setDetail(detail);
83	        problemDetail.setProperty("timestamp", Instant.now());
84	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
85	        return problemDetail;
86	    }
87	
88	    /**
89	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
90	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
91	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
92	     * would catch it and report an authorization failure as a 500.
93	     *
94	     * @param e The {@link AccessDeniedException} to propagate
95	     * @throws AccessDeniedException always
96	     */
97	    @ExceptionHandler(AccessDeniedException.class)
98	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
99	        throw e;
100	    }
101	
102	    /**
103	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
104	     *
105	     * @param e The {@link Exception} to be handled
106	     * @param request {@link HttpServletRequest} object referring to the current request.
107	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
108	     */
109	    @ExceptionHandler(Exception.class)
110	    @ResponseBody
111	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
112	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
113	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
114	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
115	        return ResponseEntity.status(status).body(detail);
116	    }
117	
118	    /**
119	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
120	     * method returns a 404 Not Found status if an entity does not exist.
121	     *
122	     * @param e The {@link DataIntegrityViolationException} to be handled
123	     * @param request {@link HttpServletRequest} object referring to the current request.
124	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
125	     */
126	    @ExceptionHandler(DataIntegrityViolationException.class)
127	    @ResponseBody
128	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
129	        logger.warn("Data integrity violation at {} {}: {}",
130	            request.getMethod(),
131	            request.getRequestURI(),
132	            e.getMessage());
133	        logger.debug("Data integrity violation stacktrace", e);
134	        HttpStatus status = HttpStatus.NOT_FOUND;
135	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
136	        return ResponseEntity.status(status).body(detail);
137	    }
138	
139	    /**
140	     * Handles exception thrown by Bean Validation on controller methods parameters
141	     *
142	     * @param e The {@link MethodArgumentNotValidException} to be handled
143	     * @param request {@link HttpServletRequest} object referring to the current request.
144	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
145	     */
146	    @ExceptionHandler(MethodArgumentNotValidException.class)
147	    @ResponseBody
148	    public ResponseEntity<?> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
149	        HttpStatus status = HttpStatus.BAD_REQUEST;
150	        BindingErrorsResponse errors = new BindingErrorsResponse();
151	        BindingResult bindingResult = e.getBindingResult();
152	        if (bindingResult.getTarget() instanceof OwnerFieldsDto ownerFields) {
153	            List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFields);
154	            if (!missingFields.isEmpty()) {
155	                return ResponseEntity.status(status).body(new ValidationErrorsResponse(missingFields));
156	            }
157	        }
158	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
159	        if (bindingResult.hasErrors()) {
160	            errors.addAllErrors(bindingResult);
161	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
162	                .map(fieldError -> {
163	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
164	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
165	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
166	                        fieldError.getField(),
167	                        defaultMessage,
168	                        rejectedValue);
169	                    return new ValidationMessageDto(message)
170	                        .putAdditionalProperty("field", fieldError.getField())
171	                        .putAdditionalProperty("rejectedValue", rejectedValue)
172	                        .putAdditionalProperty("defaultMessage", defaultMessage);
173	                })
174	                .toList();
175	            logger.debug("Validation error at {} {}: {}",
176	                request.getMethod(),
177	                request.getRequestURI(),
178	                bindingResult.getFieldErrors());
179	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
180	            return ResponseEntity.status(status).body(detail);
181	        }
182	        return ResponseEntity.status(status).body(detail);
183	    }
184	
185	    /**
186	     * Handles {@link MissingOwnerFieldsException} raised when an owner is created with required
187	     * fields that are missing or blank. Returns a 400 Bad Request whose {@code errors} array lists
188	     * the name of each offending field.
189	     *
190	     * @param e The {@link MissingOwnerFieldsException} to be handled
191	     * @return A {@link ResponseEntity} containing the offending field names and a 400 Bad Request status.
192	     */
193	    @ExceptionHandler(MissingOwnerFieldsException.class)
194	    @ResponseBody
195	    public ResponseEntity<ValidationErrorsResponse> handleMissingOwnerFieldsException(MissingOwnerFieldsException e) {
196	        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(new ValidationErrorsResponse(e.getFields()));
197	    }
198	
199	    /**
200	     * Handles {@link InvalidTelephoneException} raised when an owner's telephone does not
201	     * reduce to exactly ten digits. Returns a 400 Bad Request whose {@code errors} array
202	     * names the offending field.
203	     *
204	     * @param e The {@link InvalidTelephoneException} to be handled
205	     * @return A {@link ResponseEntity} containing the offending field name and a 400 Bad Request status.
206	     */
207	    @ExceptionHandler(InvalidTelephoneException.class)
208	    @ResponseBody
209	    public ResponseEntity<ValidationErrorsResponse> handleInvalidTelephoneException(InvalidTelephoneException e) {
210	        logger.debug("Invalid telephone: {}", e.getMessage());
211	        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
212	            .body(new ValidationErrorsResponse(List.of(InvalidTelephoneException.FIELD)));
213	    }
214	
215	    /**
216	     * Handles {@link InvalidEmailException} raised when an owner's email is present but is
217	     * not a syntactically valid address. Returns a 400 Bad Request whose {@code errors}
218	     * array names the offending field.
219	     *
220	     * @param e The {@link InvalidEmailException} to be handled
221	     * @return A {@link ResponseEntity} containing the offending field name and a 400 Bad Request status.
222	     */
223	    @ExceptionHandler(InvalidEmailException.class)
224	    @ResponseBody
225	    public ResponseEntity<ValidationErrorsResponse> handleInvalidEmailException(InvalidEmailException e) {
226	        logger.debug("Invalid email: {}", e.getMessage());
227	        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
228	            .body(new ValidationErrorsResponse(List.of(InvalidEmailException.FIELD)));
229	    }
230	
231	    /**
232	     * Handles {@link DuplicateTelephoneException} raised when an owner is created with a
233	     * normalized telephone that is already used by another owner. Returns a 409 Conflict
234	     * whose {@code errors} array names the offending field.
235	     *
236	     * @param e The {@link DuplicateTelephoneException} to be handled
237	     * @return A {@link ResponseEntity} containing the offending field name and a 409 Conflict status.
238	     */
239	    @ExceptionHandler(DuplicateTelephoneException.class)
240	    @ResponseBody
241	    public ResponseEntity<ValidationErrorsResponse> handleDuplicateTelephoneException(DuplicateTelephoneException e) {
242	        logger.debug("Duplicate telephone: {}", e.getMessage());
243	        return ResponseEntity.status(HttpStatus.CONFLICT)
244	            .body(new ValidationErrorsResponse(List.of(DuplicateTelephoneException.FIELD)));
245	    }
246	
247	    /**
248	     * Handles {@link DuplicateHouseholdException} raised when an owner is created whose last
249	     * name and address already belong to another owner and the request did not opt in via
250	     * {@code sharesHousehold}. Returns a 409 Conflict whose {@code errors} array names the
251	     * offending fields.
252	     *
253	     * @param e The {@link DuplicateHouseholdException} to be handled
254	     * @return A {@link ResponseEntity} containing the offending field names and a 409 Conflict status.
255	     */
256	    @ExceptionHandler(DuplicateHouseholdException.class)
257	    @ResponseBody
258	    public ResponseEntity<ValidationErrorsResponse> handleDuplicateHouseholdException(DuplicateHouseholdException e) {
259	        logger.debug("Duplicate household: {}", e.getMessage());
260	        return ResponseEntity.status(HttpStatus.CONFLICT)
261	            .body(new ValidationErrorsResponse(DuplicateHouseholdException.FIELDS));
262	    }
263	
264	}
