@Component
public class EmailNormalizer {

    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");

    public String normalize(String email) {
        if (email == null) {
            return null;
        }
        if (!EMAIL.matcher(email).matches()) {
